  'X-API-Key': '<X-API-Key>',
  'Content-Type': 'application/json'
}
conn.request("POST", "/proxy/protect/integration/v1/pos/cameras/{id}/transactions", payload, headers)
res = conn.getresponse()
data = res.read()
print(data.decode("utf-8"))

